def _setup():
    cells = {}
    for k in KARKAND_CELLS.keys():
        v = KARKAND_CELLS[k]
        if not isinstance(v, str):
            v = ''.join(v)
        cells[k] = v
    faces = ''.join(KARKAND_FACES)
    MAPS['strike_at_karkand'] = {'names': KARKAND_NAMES, 'faces': faces, 'cells': cells, 'n': len(faces) // 23,
        'cache': {}, 'cell_cache': {}, 'where': 'the 36 spawn points and 8 flags of Conquest 64 (main base left out)'}

_setup()
del KARKAND_FACES
del KARKAND_CELLS
